/// Next improvement: Take the next improvement card to work on.
@MainActor
public enum ImprovementNextAction {
    public static let id = "improvement_next"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (ImprovementNextInput) async throws -> ImprovementNextOutput)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (ImprovementNextInput, Result<ImprovementNextOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: ImprovementNextInput) async throws -> ImprovementNextOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct ImprovementNextIntent: AppIntent {
    public static let title: LocalizedStringResource = "Next improvement"
    public static let description = IntentDescription("Use when you take on improvement work: take the next improvement card, the open card that waited longest. It claims the card for a limited time and returns it with the `claim_id` and the authority statement. A refusal comes back as `status` (claim_held, cap_reached, none_open, too_many_cards, machine_key_unavailable or noninteractive) with a one-line `meaning`. Optional `session` is the session's UUID.")

    @Parameter(title: "Session", description: "The session's UUID, when known.")
    public var session: String?

    public init() {}

    public init(_ input: ImprovementNextInput) {
        self.init()
        self.session = input.session
    }

    public var input: ImprovementNextInput {
        ImprovementNextInput(session: session)
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<ImprovementNextOutput, any Error>
        do { result = .success(try await ImprovementNextAction.run(input)) } catch { result = .failure(error) }
        if let dialog = ImprovementNextAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

